using Aspose.Cells;
using Aspose.Cells.Rendering;
using System;
using System.IO;

// The example loads an Excel template that contains smart markers, optionally processes them, configures PdfSaveOptions with OnePagePerSheet set to false, and saves the workbook as a PDF. This ensures that charts and graphics generated by smart markers are retained in the exported PDF.
class ExportWorkbookToPdf
{
    static void Main()
    {
        try
        {
            const string templatePath = "SmartMarkerTemplate.xlsx";
            const string outputPath = "ExportedWorkbook.pdf";

            // Verify that the template file exists before loading.
            if (!File.Exists(templatePath))
            {
                Console.WriteLine($"Error: Template file \"{templatePath}\" not found.");
                return;
            }

            // Load the workbook that contains smart markers, charts and other graphics.
            Workbook workbook = new Workbook(templatePath);

            // OPTIONAL: Process smart markers with your data source.
            // var dataSource = GetYourDataSource();
            // new SmartMarkerProcessor(workbook).Process(dataSource);

            // Configure PDF save options to ensure all visual elements are rendered.
            PdfSaveOptions pdfOptions = new PdfSaveOptions
            {
                // Keep the original layout; do not force everything onto a single page.
                OnePagePerSheet = false
                // Additional options such as PDF/A compliance can be set here if required.
                // Compliance = PdfCompliance.PdfA1b
            };

            // Export the populated workbook to PDF. Charts and graphics generated by smart markers are preserved.
            workbook.Save(outputPath, pdfOptions);
            Console.WriteLine($"Workbook successfully exported to \"{outputPath}\".");
        }
        catch (Exception ex)
        {
            // Log or display the exception details for troubleshooting.
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
